	void RemoveDependent(MDependable_AC* dependent);		// Remove the specified dependent from the list of dependents of this notifier	virtual void Changed(ChangeID_AC theChange, void* changeData);		// Call this to inform dependents of this notifier that it has been changed. 		// "theChange" will often contain a command number.		// "changeData" will often contain a command object. 		// Directly called often, overridden rarely.	//------------------------------------------------------------------------------------	// Dependent stuff	//------------------------------------------------------------------------------------	virtual void DoUpdate(ChangeID_AC theChange, 								MDependable_AC* changedObject,								void* changeData,								CDependencySpace_AC* dependencySpace);		// Informs this dependent that a notifier on which it is dependent has been changed.		// "theChange" will often contain a command number.		// "changeData" will often contain a command object.         // Directly called rarely, overridden often.	virtual void SetMark(bool state);		// Intended to mark (state=true) or unmark (state=false) this object. Can be used		// by dependency spaces that require marking, and overridden by objects that store the		// mark internally.		// The ACS dependency spaces do not use this method. 	virtual bool IsMarked();		// Intended to return true if this object is marked. Can be used		// by dependency spaces that require marking, and overridden by objects that store the		// mark internally.		// The ACS dependency spaces do not use this method. };#endif/*	Historical Change Record:		----- R11 -----		06/26/96	Install release marker.  Scope many globals.  Change TRUE/FALSE/NULL.		06/24/96	[1345531] Added #include "UClassDesc.h" for noload buids		04/15/96	Removed MDependable_AC::RemoveDependenciesOnFree since we will soon							stop mixing MDependent in at TObject and it will be unnecessary		04/15/96	Tax Day, split this file off separate from UObject		----- R10 -----*/